from itertools import permutations

def main():
    data = sys.stdin.buffer.read().split()
    pos = 0
    N = int(data[pos]); pos += 1

    MG = int(data[pos]); pos += 1
    g_edges = set()
    for _ in range(MG):
        u = int(data[pos]) - 1
        v = int(data[pos + 1]) - 1
        pos += 2
        g_edges.add((u, v))

    MH = int(data[pos]); pos += 1
    hf = [False] * (N * N)
    for _ in range(MH):
        a = int(data[pos]) - 1
        b = int(data[pos + 1]) - 1
        pos += 2
        hf[a * N + b] = True
        hf[b * N + a] = True

    Af = [0] * (N * N)
    for i in range(N):
        for j in range(i + 1, N):
            c = int(data[pos]); pos += 1
            Af[i * N + j] = c
            Af[j * N + i] = c

    edge_pairs = []
    nonedge_pairs = []
    for i in range(N):
        for j in range(i + 1, N):
            if (i, j) in g_edges:
                edge_pairs.append((i, j))
            else:
                nonedge_pairs.append((i, j))

    best = float('inf')
    for p in permutations(range(N)):
        cost = 0
        for i, j in nonedge_pairs:
            x = p[i] * N + p[j]
            if hf[x]:
                cost += Af[x]
        for i, j in edge_pairs:
            x = p[i] * N + p[j]
            if not hf[x]:
                cost += Af[x]
        if cost < best:
            best = cost

    print(best)

