from operator import xor

class Solution:
    def maximumSubarrayXor(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        n = len(nums)
        ans = [0] * len(queries)

        # Group queries by span d = r - l; answer them offline as d increases.
        by_len = {}
        max_d = 0
        for idx, (l, r) in enumerate(queries):
            d = r - l
            if d > max_d:
                max_d = d
            if d in by_len:
                by_len[d].append((l, idx))
            else:
                by_len[d] = [(l, idx)]

        # f[l] = XOR score of nums[l .. l+d]
        # M[l] = max XOR score over all subarrays of nums[l .. l+d]
        f = list(nums)
        M = list(nums)

        for l, idx in by_len.get(0, ()):
            ans[idx] = M[l]

        for d in range(1, max_d + 1):
            # f(l, l+d) = f(l, l+d-1) ^ f(l+1, l+d)   (Pascal's triangle mod 2)
            f = list(map(xor, f, f[1:]))
            # M(l, l+d) = max(M(l, l+d-1), M(l+1, l+d), f(l, l+d))
            M = list(map(max, M, M[1:], f))
            g = by_len.get(d)
            if g:
                for l, idx in g:
                    ans[idx] = M[l]

        return ans

