                            continue
                        s2 = vi + vj
                        # pick best g whose column differs from ci and cj
                        if g0c != ci and g0c != cj:
                            total = s2 + g0v
                        elif g1c != ci and g1c != cj:
                            total = s2 + g1v
                        else:
