def solve():
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    x = int(data[1])
    items = ([], [], [], [])
    ptr = 2
    for _ in range(n):
        v = int(data[ptr])
        a = int(data[ptr + 1])
        c = int(data[ptr + 2])
        ptr += 3
        items[v].append((a, c))

    try:
        import numpy as np
    except ImportError:
        np = None

    if np is not None:
        dps = []
        for v in (1, 2, 3):
            dp = np.zeros(x + 1, dtype=np.int64)
            for a, c in items[v]:
                if c <= x:
                    np.maximum(dp[c:], dp[:x + 1 - c] + a, out=dp[c:])
            dps.append(dp)
        d1, d2, d3 = dps
        hi = min(int(d1[x]), int(d2[x]), int(d3[x]))

        def mincost(dp, t):
            # dp is non-decreasing: first index with dp[i] >= t
            return int(np.searchsorted(dp, t, side='left'))
    else:
        dps = []
        for v in (1, 2, 3):
            dp = [0] * (x + 1)
            for a, c in items[v]:
                if c <= x:
                    m = x + 1 - c
                    dp[c:] = list(map(max, dp[c:], [q + a for q in dp[:m]]))
            dps.append(dp)
        d1, d2, d3 = dps
        hi = min(d1[x], d2[x], d3[x])

        def mincost(dp, t):
            return bisect_left(dp, t)

    lo, ans_hi = 0, hi
    while lo < ans_hi:
        mid = (lo + ans_hi + 1) // 2
        if mincost(d1, mid) + mincost(d2, mid) + mincost(d3, mid) <= x:
            lo = mid
        else:
            ans_hi = mid - 1
    print(lo)


