import sys
from itertools import accumulate
from collections import deque

def main():
    data = sys.stdin.buffer.read().split()
    N = int(data[0]); M = int(data[1])
    A = [int(x) - 1 for x in data[2:2 + N]]
    MOD = 998244353

    try:
        import numpy as np
    except Exception:
        np = None

    if np is not None:
        LEAF = np.arange(1, M + 1, dtype=np.int64)
        def vec_mul(a, b):
            return (a * b) % MOD
        def vec_psum(q):
            return np.cumsum(q) % MOD
        def vec_total(r):
            return int(r.sum()) % MOD
    else:
        LEAF = list(range(1, M + 1))
        def vec_mul(a, b, _m=MOD):
            return [x * y % _m for x, y in zip(a, b)]
        def vec_psum(q, _m=MOD):
            return [x % _m for x in accumulate(q)]
        def vec_total(r, _m=MOD):
            return sum(r) % _m

    # find cycle nodes by peeling indegree-0 nodes
    indeg = [0] * N
    for v in A:
        indeg[v] += 1
    stack = [i for i in range(N) if indeg[i] == 0]
    on_cycle = [True] * N
    while stack:
        u = stack.pop()
        on_cycle[u] = False
        v = A[u]
        indeg[v] -= 1
        if indeg[v] == 0:
            stack.append(v)

    # tree children (reverse edges, non-cycle nodes only)
    children = [[] for _ in range(N)]
    for i in range(N):
        if not on_cycle[i]:
            children[A[i]].append(i)

    # BFS from cycle nodes; reversed order => children before parents
    order = []
    dq = deque(i for i in range(N) if on_cycle[i])
    while dq:
        u = dq.popleft()
        order.append(u)
        dq.extend(children[u])

    vecs = [None] * N
    for u in reversed(order):
        if on_cycle[u]:
            continue
        ch = children[u]
        if not ch:
            vecs[u] = LEAF
        else:
            q = vecs[ch[0]]
            for w in ch[1:]:
                q = vec_mul(q, vecs[w])
            vecs[u] = vec_psum(q)
            for w in ch:
                vecs[w] = None  # free memory

    # label cycle components
    comp_id = [-1] * N
    ncomp = 0
    for u in range(N):
        if on_cycle[u] and comp_id[u] < 0:
            v = u
            while True:
                comp_id[v] = ncomp
                v = A[v]
                if v == u:
                    break
            ncomp += 1

    # subtrees hanging directly off each cycle
    comp_children = [[] for _ in range(ncomp)]
    for w in range(N):
        if not on_cycle[w] and on_cycle[A[w]]:
            comp_children[comp_id[A[w]]].append(w)

    ans = 1
    for c in range(ncomp):
        lst = comp_children[c]
        if lst:
            r = vecs[lst[0]]
            for w in lst[1:]:
                r = vec_mul(r, vecs[w])
            s = vec_total(r)
        else:
            s = M % MOD
        ans = ans * s % MOD

    print(ans % MOD)

main()

import sys
from collections import Counter


def solve_numpy(n, counters, ks, np):
    pres = Counter()
    for c in counters:
        pres.update(c.keys())
    shared = [v for v, m in pres.items() if m >= 2]
    if not shared:
        return 0.0
    vmap = {v: idx for idx, v in enumerate(shared)}
    V = len(shared)
    rows = []
    cols = []
    vals = []
    for i in range(n):
        get = vmap.get
        for v, c in counters[i].items():
            j = get(v)
            if j is not None:
                rows.append(i)
                cols.append(j)
                vals.append(c)
    M = np.zeros((n, V), dtype=np.float64)
    M[rows, cols] = vals
    S = M @ M.T
    karr = np.asarray(ks, dtype=np.float64)
    probs = S / np.outer(karr, karr)
    iu = np.triu_indices(n, k=1)
    return float(probs[iu].max())


def solve_pure(n, counters, ks):
    from operator import mul
    best = 0.0
    for i in range(n):
        di = counters[i]
        ki = ks[i]
        for j in range(i + 1, n):
            dj = counters[j]
            if len(di) <= len(dj):
                si, sj = di, dj
            else:
                si, sj = dj, di
            common = si.keys() & sj.keys()
            if not common:
                continue
            s = sum(map(mul, map(si.__getitem__, common), map(sj.__getitem__, common)))
            p = s / (ki * ks[j])
            if p > best:
                best = p
    return best


def main():
    data = sys.stdin.buffer.read().split()
    ptr = 0
    n = int(data[ptr]); ptr += 1
    ks = []
    counters = []
    for _ in range(n):
        k = int(data[ptr]); ptr += 1
        counters.append(Counter(map(int, data[ptr:ptr + k])))
        ks.append(k)
        ptr += k
    try:
        import numpy as np
    except ImportError:
        np = None
    if np is not None:
        best = solve_numpy(n, counters, ks, np)
    else:
        best = solve_pure(n, counters, ks)
    print("%.15f" % best)


