    def countPartitions(self, nums: List[int]) -> int:
        # Difference = leftSum - rightSum = 2*leftSum - totalSum
        # This is even iff totalSum is even.
        return len(nums) - 1 if sum(nums) % 2 == 0 else 0

class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        # Sort by timestamp; at equal timestamps, status changes (OFFLINE)
        # must be processed before MESSAGE events.
        sorted_events = sorted(
            events,
            key=lambda e: (int(e[1]), 0 if e[0] == "OFFLINE" else 1)
        )

        mentions = [0] * numberOfUsers
        # offline_until[u]: time at which user u comes back online.
        # User is online at time t iff offline_until[u] <= t.
        offline_until = [0] * numberOfUsers

        for etype, ts_str, payload in sorted_events:
            t = int(ts_str)
            if etype == "OFFLINE":
                u = int(payload)
                offline_until[u] = t + 60
            else:  # MESSAGE
                for token in payload.split():
                    if token == "ALL":
                        for u in range(numberOfUsers):
                            mentions[u] += 1
                    elif token == "HERE":
                        for u in range(numberOfUsers):
                            if offline_until[u] <= t:
                                mentions[u] += 1
                    else:
                        # token of the form "id<number>"
                        u = int(token[2:])
                        mentions[u] += 1

        return mentions

class Solution:
    def sortMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n = len(grid)

        # Bottom-left triangle (including main diagonal): i - j = d, d >= 0
        # Sort each such diagonal in non-increasing order.
        for d in range(n):
            cells = [(i, i - d) for i in range(d, n)]
            vals = sorted((grid[r][c] for r, c in cells), reverse=True)
            for (r, c), v in zip(cells, vals):
                grid[r][c] = v

        # Top-right triangle: j - i = d, d > 0
        # Sort each such diagonal in non-decreasing order.
        for d in range(1, n):
            cells = [(i, i + d) for i in range(n - d)]
            vals = sorted(grid[r][c] for r, c in cells)
            for (r, c), v in zip(cells, vals):
                grid[r][c] = v

        return grid

class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        maxG = max(groups)

        # Record the smallest index at which each element value occurs,
        # ignoring values that are too large to divide any group.
        first = {}
        for j, v in enumerate(elements):
            if v <= maxG and v not in first:
                first[v] = j

        INF = float('inf')
        # best[m] = smallest element index whose value divides m
        best = [INF] * (maxG + 1)

        for v, idx in first.items():
            for m in range(v, maxG + 1, v):
                if idx < best[m]:
                    best[m] = idx

        return [best[g] if best[g] != INF else -1 for g in groups]

class Solution:
    def maxDistance(self, s: str, k: int) -> int:
        ans = 0
        # Four diagonal directions; each tuple holds the two "good" characters
        for a, b in (('N', 'E'), ('S', 'E'), ('N', 'W'), ('S', 'W')):
            bad = 0
            best = 0
            for i, ch in enumerate(s, 1):
                if ch != a and ch != b:
                    bad += 1
                # With up to k fixes, projection value at prefix i:
                cur = i if bad <= k else i - 2 * (bad - k)
                if cur > best:
                    best = cur
            if best > ans:
                ans = best
        return ans

