class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        m = len(conflictingPairs)
        by_hi = [[] for _ in range(n + 1)]
        for i, pair in enumerate(conflictingPairs):
            a, b = pair
            if a > b:
                a, b = b, a
            # pair is active for right endpoint r >= b, forcing left bound >= a+1
            by_hi[b].append((a + 1, i))

        gain = [0] * m
        base = 0
        best1 = 1   # largest active constraint on left bound (min allowed l)
        best2 = 1   # second largest constraint
        idx1 = -1   # pair index achieving best1

        for r in range(1, n + 1):
            for val, i in by_hi[r]:
                if val > best1:
                    best2 = best1
                    best1 = val
                    idx1 = i
                elif val > best2:
                    best2 = val
            base += r - best1 + 1
            if best1 > best2:
                gain[idx1] += best1 - best2

        return base + (max(gain) if m > 0 else 0)

