class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        parent = list(range(n))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a, b):
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[ra] = rb

        # Bitmask of distinct values for each property
        masks = []
        for prop in properties:
            mask = 0
            for v in set(prop):
                mask |= 1 << v
            masks.append(mask)

