class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        # remaining counts of odd / even numbers in 1..n
        rem_o = (n + 1) // 2
        rem_e = n // 2

        used = [False] * (n + 1)
        result = []
        prev_parity = -1  # 1 = odd, 0 = even, -1 = none yet

        for pos in range(n):
            rem_after = n - pos - 1  # positions remaining after placing current
            placed = False
            for cand in range(1, n + 1):
                if used[cand]:
                    continue
                p = cand & 1
                if p == prev_parity:
                    continue

                if rem_after == 0:
                    cnt = 1
                else:
                    # parity pattern of remaining positions, first one is 1-p
                    start = 1 - p
                    n_start = (rem_after + 1) // 2
                    n_other = rem_after // 2
                    if start == 1:
                        po, pe = n_start, n_other
                    else:
                        po, pe = n_other, n_start
                    ro = rem_o - (1 if p == 1 else 0)
                    re = rem_e - (1 if p == 0 else 0)
                    if ro == po and re == pe:
                        cnt = fact[ro] * fact[re]
                    else:
                        cnt = 0

                if cnt == 0:
                    continue
                if k > cnt:
                    k -= cnt
                    continue

                # place candidate
                used[cand] = True
                if p == 1:
                    rem_o -= 1
                else:
                    rem_e -= 1
                result.append(cand)
                prev_parity = p
                placed = True
                break

            if not placed:
                return []

        return result

