class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        # pw[j] = 4^j, pref[j] = sum of d(x) for x in [1, 4^j - 1]
        MAXJ = 17  # 4^16 > 1e9, plenty of headroom
        pw = [1] * (MAXJ + 1)
        for j in range(1, MAXJ + 1):
            pw[j] = pw[j - 1] * 4
        pref = [0] * (MAXJ + 1)
        for j in range(1, MAXJ + 1):
            pref[j] = pref[j - 1] + j * (pw[j] - pw[j - 1])

        def F(n):
            # sum of d(x) for x in [1, n]
            if n <= 0:
                return 0
            K = (n.bit_length() + 1) // 2  # d(n) tier: 4^(K-1) <= n <= 4^K - 1
            return pref[K - 1] + K * (n - pw[K - 1] + 1)

        total = 0
        for l, r in queries:
            s = F(r) - F(l - 1)
            total += (s + 1) // 2
        return total

