    def findMinimumTime(self, strength: List[int], K: int) -> int:
        n = len(strength)
        full = (1 << n) - 1
        INF = float('inf')
        dp = [INF] * (full + 1)
        dp[0] = 0
        for mask in range(full + 1):
            cur = dp[mask]
            if cur == INF:
                continue
            x = 1 + K * bin(mask).count('1')
            for i in range(n):
                bit = 1 << i
                if mask & bit:
                    continue
                cost = (strength[i] + x - 1) // x  # ceil(strength[i] / x)
                nm = mask | bit
                if cur + cost < dp[nm]:
                    dp[nm] = cur + cost
        return dp[full]

